public static int countOilDeposits(char[][] grid) {
    // Initialize a hash set to keep track of visited plots
    HashSet<String> visited = new HashSet<>();

    // Initialize the number of oil deposits to 0
    int numDeposits = 0;

    // Loop through each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // Loop through each column of the grid
        for (int j = 0; j < grid[0].length; j++) {
            // If the current plot is an oil pocket
            if (grid[i][j] == '@') {
                // Add the plot to the visited set
                visited.add(getPlotHash(i, j, grid));

                // Increment the number of oil deposits
                numDeposits++;

                // Recursively explore the surrounding plots
                exploreNeighbors(i, j, grid, visited);
            }
        }
    }

    return numDeposits;
}

// A utility function to get the hash code of a plot
private static String getPlotHash(int i, int j, char[][] grid) {
    return i + ":" + j + ":" + grid[i][j];
}

// A utility function to explore the surrounding plots of a given plot
private static void exploreNeighbors(int i, int j, char[][] grid, HashSet<String> visited) {
    // Loop through each neighbor of the current plot
    for (int[] neighbor : getNeighbors(i, j)) {
        // If the neighbor is an oil pocket and not yet visited
        if (grid[neighbor[0]][neighbor[1]] == '@' && !visited.contains(getPlotHash(neighbor[0], neighbor[1], grid))) {
            // Add the neighbor to the visited set
            visited.add(getPlotHash(neighbor[0], neighbor[1], grid));

            // Recursively explore the surrounding plots of the neighbor
            exploreNeighbors(neighbor[0], neighbor[1], grid, visited);
        }
    }
}

// A utility function to get the neighbors of a given plot
private static int[][] getNeighbors(int i, int j) {
    return new int[][] {{i - 1, j}, {i, j - 1}, {i + 1, j}, {i, j + 1}};
}

