        adjacencyList[path[1]][path[0]] = 1;
    }
    // Fill in the remaining elements of the adjacency list with 0s
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (adjacencyList[i][j] == 0) {
                adjacencyList[i][j] = 1;
            }
        }
    }
    // Initialize a set to keep track of visited vertices
    Set<int[]> visitedVertices = new HashSet<>();
    // Create a queue to traverse the n-teresting space
    Queue<int[]> queue = new LinkedList<>();
    // Enqueue the starting n-tersection
    queue.offer(start);
    // While the queue is not empty
    while (!queue.isEmpty()) {
        // Dequeue the front vertex
        int[] frontVertix = queue.poll();
        // If the front vertex is the ending n-tersection
        if (Arrays.equals(frontVertix, end)) {
            // Return "can be travelled"
            return "can be travelled";
        }
        // If the front vertex has not been visited yet
        if (!visitedVertices.contains(frontVertix)) {
            // Add it to the set of visited vertices
            visitedVertices.add(frontVertix);
            // For each adjacent n-tersection
            for (int i = 0; i < n; i++) {
                // If the adjacency list has a connection between the front vertex and the adjacent n-tersection
                if (adjacencyList[frontVertix[0]][i] == 1) {
                    // Add the adjacent n-tersection to the queue
                    queue.offer(new int[]{i, frontVertix[1]});
                }
            }
        }
    }
    // Return "cannot be travelled"
    return "cannot be travelled";
}
