    int totalElements = arr.length;

    // calculate the number of elements to be removed from the smallest 5%
    int numToRemoveSmallest = (int) (totalElements * 0.05);

    // calculate the number of elements to be removed from the largest 5%
    int numToRemoveLargest = (int) (totalElements * 0.05);

    // remove the smallest 5% of elements
    for (int i = 0; i < numToRemoveSmallest; i++) {
        arr[i] = arr[totalElements - numToRemoveSmallest + i];
    }

    // remove the largest 5% of elements
    for (int i = 0; i < numToRemoveLargest; i++) {
        arr[totalElements - numToRemoveLargest + i] = arr[totalElements - numToRemoveSmallest + i];
    }

    // calculate the mean of the remaining elements
    double mean = 0;
    for (int i = 0; i < totalElements - 2 * numToRemoveSmallest - numToRemoveLargest; i++) {
        mean += arr[i];
    }
    mean /= (totalElements - 2 * numToRemoveSmallest - numToRemoveLargest);

