public boolean canArrange(int[] arr, int k) {
    // Check if the length of the array is even
    if (arr.length % 2 != 0) {
        return false;
    }

    // Create a set to store the odd elements
    Set<Integer> oddSet = new HashSet<>();
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] % 2 != 0) {
            oddSet.add(arr[i]);
        }
    }

    // If there are an odd number of odd elements, return false
    if (oddSet.size() % 2 != 0) {
        return false;
    }

    // Create a map to store the sum of each pair
    Map<Integer, Integer> pairSumMap = new HashMap<>();
    for (int i = 0; i < arr.length; i += 2) {
        int sum = arr[i] + arr[i + 1];
        if (pairSumMap.containsKey(sum)) {
            pairSumMap.put(sum, pairSumMap.get(sum) + 1);
        } else {
            pairSumMap.put(sum, 1);
        }
    }

    // Check if there are any pairs with a sum that is not divisible by k
    for (Map.Entry<Integer, Integer> entry : pairSumMap.entrySet()) {
        if (entry.getKey() % k != 0) {
            return false;
        }
    }

    return true;
