  // Initialize the pairs counter
  int pairs = 0;

  // Iterate over the array
  for (int i = 0; i < arr.length - 1; i++) {
    // Check if the current element is divisible by the k
    if (arr[i] % k == 0) {
      // Increment the pairs counter
      pairs++;

      // Check if the next element is also divisible by the k
      if (arr[i + 1] % k == 0) {
        // Increment the pairs counter
        pairs++;
      }
    }
  }

  // Check if the pairs counter is equal to the array length divided by 2
  return pairs == arr.length / 2;
