public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to store the counts of each number
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : arr) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }

    // Initialize two pointers for the starting and ending indices of the pairs
    int start = 0, end = arr.length - 1;

    // Loop through the array and increment the count of each number
    while (start < end) {
        // If the count of the number at the starting index is odd, we cannot form a pair
        if (counts.get(arr[start]) % 2 == 1) {
            return false;
        }

        // If the count of the number at the ending index is odd, we cannot form a pair
        if (counts.get(arr[end]) % 2 == 1) {
            return false;
        }

        // If the sum of the numbers at the starting and ending indices is divisible by k,
        // we can form a pair and increment the starting and ending indices
        if (arr[start] + arr[end] % k == 0) {
            start++;
            end--;
        } else {
            // If the sum of the numbers at the starting and ending indices is not divisible by k,
            // we cannot form a pair and need to move the ending index back
            end--;
        }
    }

    // If the starting index has reached the ending index, we have formed n/2 pairs
    return start == end;
