    Graph graph = new Graph(n);

    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Step 2: Perform a DFS from node 0, exploring the graph and keeping track of the minimum time required to collect all apples
    int[] dist = new int[n];
    boolean[] visited = new boolean[n];
    int time = 0;

    dfs(graph, 0, dist, visited, hasApple, time);

    // Step 3: Return the minimum time required to collect all apples
    return time;
