private void dfs(Graph graph, int node, int[] dist, boolean[] visited, boolean[] hasApple, int time) {
    // Step 1: Mark the current node as visited and update the minimum time required to collect all apples
    visited[node] = true;
    if (hasApple[node]) {
        time++;
    }

    // Step 2: Explore the children of the current node
    for (int neighbor : graph.getNeighbors(node)) {
        if (!visited[neighbor]) {
            // Step 3: Recursively explore the unvisited child
            dfs(graph, neighbor, dist, visited, hasApple, time);

            // Step 4: Update the minimum time required to collect all apples
            if (hasApple[node]) {
                dist[node] = Math.min(dist[node], time);
            }
        }
    }
}

