public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (true) {
        boolean allEqual = true;
        for (int i = 0; i < n; i++) {
            if (arr[i] != arr[0]) {
                allEqual = false;
                break;
            }
        }
        if (allEqual) {
            break;
        }

        int[] counts = new int[n];
        for (int i = 0; i < n; i++) {
            counts[i] = arr[i] - arr[0];
        }

        for (int i = 0; i < n; i++) {
            if (counts[i] < 0) {
                minOperations++;
                arr[i] += 1;
            } else if (counts[i] > 0) {
                minOperations++;
                arr[i] -= 1;
            }
        }
    }

    return minOperations;
}

