public int maxAbsoluteSum(int[] nums) {
    // Base case: If the input array has only one element, return its absolute value
    if (nums.length == 1) {
        return Math.abs(nums[0]);
    }

    // Initialize the maximum absolute sum and the current sum
    int maxAbsSum = Math.abs(nums[0]) + Math.abs(nums[1]);
    int currSum = Math.abs(nums[0]) + Math.abs(nums[1]);

    // Iterate over the rest of the array
    for (int i = 2; i < nums.length; i++) {
        // Add the current element to the current sum
        currSum += Math.abs(nums[i]);

        // Compare the current sum with the maximum absolute sum, and update it if necessary
        maxAbsSum = Math.max(maxAbsSum, currSum);

        // If the current sum is negative, reset it to zero
        // Note: This assumes that the input array elements are all non-negative
        if (currSum < 0) {
            currSum = 0;
        }
    }

    return maxAbsSum;
}
