public int kthFactor(int n, int k) {
    // Initialize a set to store the factors of n
    Set<Integer> factors = new HashSet<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i <= (int)Math.sqrt(n); i++) {
        // If i divides n evenly, add it to the set of factors
        if (n % i == 0) {
            factors.add(i);
            // If we have found k factors, return the kth factor
            if (factors.size() == k) {
                return factors.toArray(new Integer[0])[k - 1];
            }
        }
    }

    // If we did not find k factors, return -1
    return -1;
}
