public int maxUniqueSplit(String s) {
    // Create a HashSet to keep track of unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Initialize the maximum number of unique substrings
    int maxUniqueSubstrings = 0;

    // Loop through each character in the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character
        char c = s.charAt(i);

        // If the current character is not a whitespace character, add it to the HashSet
        if (!Character.isWhitespace(c)) {
            uniqueSubstrings.add(String.valueOf(c));
        }

        // If the current character is a whitespace character, remove the last substring
        // from the HashSet if it is a whitespace character
        else if (Character.isWhitespace(c) && !uniqueSubstrings.isEmpty()) {
            String lastSubstring = uniqueSubstrings.iterator().next();

            if (Character.isWhitespace(lastSubstring.charAt(0))) {
                uniqueSubstrings.remove(lastSubstring);
            }
        }

        // Update the maximum number of unique substrings
        maxUniqueSubstrings = Math.max(maxUniqueSubstrings, uniqueSubstrings.size());
    }

    return maxUniqueSubstrings;
}
