                if (i == 0 || j == 0 || i == mat.length - 1 || j == mat[0].length - 1) {
                    // If the current element is at the edge of the matrix,
                    // the longest line length is the current line length
                    longestLineLength = Math.max(longestLineLength, currentLineLength);
                } else {
