public static int calculateEnergy(String s) {
    // Initialize variables
    int maxLength = 0;
    int currentLength = 0;

    // Iterate over the string
    for (int i = 0; i < s.length(); i++) {
        // Check if the current character is the same as the previous character
        if (i == 0 || s.charAt(i) == s.charAt(i - 1)) {
            // If the current character is the same as the previous character, increment the current length
            currentLength++;
        } else {
            // If the current character is not the same as the previous character, update the maximum length
            maxLength = Math.max(maxLength, currentLength);
            // Reset the current length
            currentLength = 1;
        }
    }

    // Update the maximum length with the final current length
    maxLength = Math.max(maxLength, currentLength);

    return maxLength;
}

