public static int minPerfectSquareSum(int n) {
    // Initialize a set to store the perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Loop through the range of numbers from 1 to n
    for (int i = 1; i <= n; i++) {
        // If the current number is a perfect square, add it to the set
        if (Math.sqrt(i) % 1 == 0) {
            perfectSquares.add(i);
        }
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minPerfectSquareSum = Integer.MAX_VALUE;

    // Loop through the set of perfect square numbers
    for (Integer perfectSquare : perfectSquares) {
        // Calculate the sum of the current perfect square number with all the other perfect square numbers
        int sum = perfectSquare;
        for (Integer otherPerfectSquare : perfectSquares) {
            if (otherPerfectSquare != perfectSquare) {
                sum += otherPerfectSquare;
            }
        }

        // If the sum is less than the minimum, update the minimum
        if (sum < minPerfectSquareSum) {
            minPerfectSquareSum = sum;
        }
    }

    // Return the minimum number of perfect square numbers
    return minPerfectSquareSum;
}
